import sys

# Test cases for batch_size validation
def test_positive_batch_size():
    def enqueue(task):
        return execute(task, lambda owner, bs: (owner, bs))
    assert submit('owner1', enqueue, 10) == ('owner1', 10)
    assert submit('owner2', enqueue) == ('owner2', 20)

def test_invalid_batch_size():
    def enqueue(task):
        return execute(task, lambda owner, bs: (owner, bs))
    try:
        submit('owner', enqueue, 0)
        assert False, "Expected ValueError for batch_size=0"
    except ValueError:
        pass

    try:
        submit('owner', enqueue, 101)
        assert False, "Expected ValueError for batch_size=101"
    except ValueError:
        pass

    try:
        submit('owner', enqueue, True)
        assert False, "Expected ValueError for bool batch_size"
    except ValueError:
        pass

